import SwiftUI

struct FinanceCalendarSheet: View { @EnvironmentObject private var store: LedgerStore; @Environment(\.dismiss) private var dismiss; @State private var month = Date(); @State private var selected = Date()
    private var days: [Date] { let calendar = Calendar.current; let start = calendar.dateInterval(of: .month, for: month)!.start; let count = calendar.range(of: .day, in: .month, for: month)!.count; return (0..<count).compactMap { calendar.date(byAdding: .day, value: $0, to: start) } }
    var body: some View { NavigationStack { List { Section { HStack { Button { month = Calendar.current.date(byAdding: .month, value: -1, to: month)! } label: { Image(systemName: "chevron.left") }; Spacer(); Text(month.formatted(.dateTime.year().month())); Spacer(); Button { month = Calendar.current.date(byAdding: .month, value: 1, to: month)! } label: { Image(systemName: "chevron.right") } } }; LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 7)) { ForEach(days, id: \.self) { day in let amount = store.transactions.filter { Calendar.current.isDate($0.happenedAt, inSameDayAs: day) && $0.kind == .expense }.reduce(0) { $0 + $1.amount }; Button { selected = day } label: { VStack { Text(day.formatted(.dateTime.day())); if amount > 0 { Text("¥\(amount, specifier: "%.0f")").font(.caption2).foregroundStyle(.orange) } }.frame(height: 46).frame(maxWidth: .infinity).background(Calendar.current.isDate(day, inSameDayAs: selected) ? Color.blue.opacity(0.18) : .clear, in: RoundedRectangle(cornerRadius: 8)) }.foregroundStyle(.primary) } } }; Section(selected.formatted(date: .complete, time: .omitted)) { ForEach(store.transactions.filter { Calendar.current.isDate($0.happenedAt, inSameDayAs: selected) }) { TransactionRow(transaction: $0) } } }.navigationTitle("财务日历").toolbar { Button("今天") { month = Date(); selected = Date() }; ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } } } } }
}
